head.script:
// 기존 스크립트 유지 (원본 Def.xml에서 가져온 스크립트)
scwin.pageInfo = {
	waiting: { currentPage: 1, pageSize: 10, totalCount: 0, data: [] },
	processing: { currentPage: 1, pageSize: 10, totalCount: 0, data: [] },
	completed: { currentPage: 1, pageSize: 10, totalCount: 0, data: [] }
};

scwin.onpageload = function() {
	scwin.initPaginationInfo();
	dmp_defVo.set("pageIndex", "1");
	dmp_defVo.set("pageSize", "1000");

	var searchBoxComp = $p.getComponentById("search_box");
	var searchComp1 = $p.getComponentById("searchComp_1");
	if (searchBoxComp && searchComp1 == undefined) {
		searchBoxComp.hide();
	}

	scwin.btn_search_onclick();
};

scwin.initPaginationInfo = function() {
	scwin.pageInfo = {
		waiting: { currentPage: 1, pageSize: 10, totalCount: 0, data: [] },
		processing: { currentPage: 1, pageSize: 10, totalCount: 0, data: [] },
		completed: { currentPage: 1, pageSize: 10, totalCount: 0, data: [] }
	};
};

scwin.getPageData = function(data, pageInfo) {
	if (!data || !pageInfo) return [];
	var startIndex = (pageInfo.currentPage - 1) * pageInfo.pageSize;
	var endIndex = startIndex + pageInfo.pageSize;
	return data.slice(startIndex, endIndex);
};

scwin.updatePagination = function(pageInfo, paginationComponent) {
	if (!pageInfo || !paginationComponent) return;
	var totalPages = Math.ceil(pageInfo.totalCount / pageInfo.pageSize);
	if (totalPages > 0) {
		paginationComponent.setCount(totalPages);
		paginationComponent.setSelectedIndex(pageInfo.currentPage);
	}
};

scwin.btn_search_onclick = function(e) {
	dmp_defVo.set("pageIndex", "1");
	$c.sbm.execute($p, sbm_selectDefVoList);
};

scwin.sbm_defList_submitdone = function(e) {
	var elData = e.responseJSON.elData;
	var elHeader = e.responseJSON.elHeader;

	if (!elHeader || elHeader.resSuc == false) {
		$c.win.alert(`에러코드 : ${elHeader.resCode}\n에러메시지 : ${elHeader.resMsg}`);
		return false;
	}

	var allData = elData.defVoList || [];
	var waitingData = [];
	var processingData = [];
	var completedData = [];

	for (var i = 0; i < allData.length; i++) {
		var item = allData[i];
		if (item.status === "NEW") {
			waitingData.push(item);
		} else if (item.status === "IPR") {
			processingData.push(item);
		} else if (item.status === "COM" || item.status === "FIX") {
			completedData.push(item);
		}
	}

	scwin.pageInfo.waiting.data = waitingData;
	scwin.pageInfo.waiting.totalCount = waitingData.length;
	scwin.pageInfo.processing.data = processingData;
	scwin.pageInfo.processing.totalCount = processingData.length;
	scwin.pageInfo.completed.data = completedData;
	scwin.pageInfo.completed.totalCount = completedData.length;

	scwin.updateGridData();
	scwin.updatePagination(scwin.pageInfo.waiting, pgl_defList_new);
	scwin.updatePagination(scwin.pageInfo.processing, pgl_defList_processing);
	scwin.updatePagination(scwin.pageInfo.completed, pgl_defList_completed);

	spn_waitListCnt.setLabel(waitingData.length);
	spn_processingListCnt.setLabel(processingData.length);
	spn_completeListCnt.setLabel(completedData.length);
	spn_listCnt.setLabel(allData.length);

	dmp_defVoDetail.setEmptyValue();
};

scwin.updateGridData = function() {
	try {
		if (scwin.pageInfo.waiting && scwin.pageInfo.waiting.data) {
			var waitingPageData = scwin.getPageData(scwin.pageInfo.waiting.data, scwin.pageInfo.waiting);
			dlt_waitingList.setJSON(waitingPageData);
		}

		if (scwin.pageInfo.processing && scwin.pageInfo.processing.data) {
			var processingPageData = scwin.getPageData(scwin.pageInfo.processing.data, scwin.pageInfo.processing);
			dlt_processingList.setJSON(processingPageData);
		}

		if (scwin.pageInfo.completed && scwin.pageInfo.completed.data) {
			var completedPageData = scwin.getPageData(scwin.pageInfo.completed.data, scwin.pageInfo.completed);
			dlt_completedList.setJSON(completedPageData);
		}
	} catch (err) {
		console.error("그리드 데이터 업데이트 오류:", err);
	}
};

scwin.pgl_defList_new_onclick = function(idx) {
	if (!scwin.pageInfo.waiting) return;
	scwin.pageInfo.waiting.currentPage = idx;
	var waitingPageData = scwin.getPageData(scwin.pageInfo.waiting.data, scwin.pageInfo.waiting);
	dlt_waitingList.setJSON(waitingPageData);
	pgl_defList_new.setSelectedIndex(idx);
};

scwin.pgl_defList_processing_onclick = function(idx) {
	if (!scwin.pageInfo.processing) return;
	scwin.pageInfo.processing.currentPage = idx;
	var processingPageData = scwin.getPageData(scwin.pageInfo.processing.data, scwin.pageInfo.processing);
	dlt_processingList.setJSON(processingPageData);
	pgl_defList_processing.setSelectedIndex(idx);
};

scwin.pgl_defList_completed_onclick = function(idx) {
	if (!scwin.pageInfo.completed) return;
	scwin.pageInfo.completed.currentPage = idx;
	var completedPageData = scwin.getPageData(scwin.pageInfo.completed.data, scwin.pageInfo.completed);
	dlt_completedList.setJSON(completedPageData);
	pgl_defList_completed.setSelectedIndex(idx);
};

// 그리드 더블클릭 이벤트
scwin.new_grd_oncelldblclick = function(rowIndex, columnIndex, columnId) {
	dmp_defVoDetail.setJSON(dlt_waitingList.getRowJSON(rowIndex));
	spn_popupTitle.setValue("신규 결함 상세정보");
	scwin.setFormMode("view");
	pop_overlay.show();
	scwin.loadFileList();
};

scwin.processing_grd_oncelldblclick = function(rowIndex, columnIndex, columnId) {
	dmp_defVoDetail.setJSON(dlt_processingList.getRowJSON(rowIndex));
	spn_popupTitle.setValue("진행중 결함 상세정보");
	scwin.setFormMode("view");
	pop_overlay.show();
	scwin.loadFileList();
};

scwin.completed_grd_oncelldblclick = function(rowIndex, columnIndex, columnId) {
	dmp_defVoDetail.setJSON(dlt_completedList.getRowJSON(rowIndex));
	spn_popupTitle.setValue("완료 결함 상세정보");
	scwin.setFormMode("view");
	pop_overlay.show();
	scwin.loadFileList();
};

// 결함 등록
scwin.reg_btn_onclick = function(e) {
	dmp_defVoDetail.setEmptyValue();
	dmp_defVoDetail.set("testId", "6");
	dmp_defVoDetail.set("testName", "ERP 시스템 단위테스트");
	dmp_defVoDetail.set("assignee", "1");
	dmp_defVoDetail.set("userName", "김개발");
	dmp_defVoDetail.set("status", "NEW");
	dmp_defVoDetail.set("priority", "MD");

	dlt_Upload.setJSON([]);
	spn_popupTitle.setValue("결함 등록");
	scwin.setFormMode("register");
	pop_overlay.show();
};

// 팝업 닫기
scwin.detail_esc_btn_onclick = function(e) {
	pop_overlay.hide();
};

// 폼 모드 설정
scwin.setFormMode = function(mode) {
	if (mode === "register") {
		btn_popup_save.show();
		btn_popup_edit.hide();
		btn_popup_delete.hide();
		grp_fileUpload.show();
		scwin.setFieldsReadOnly(false);
	} else if (mode === "view") {
		btn_popup_save.hide();
		btn_popup_edit.show();
		btn_popup_delete.show();
		grp_fileUpload.hide();
		scwin.setFieldsReadOnly(true);
	} else if (mode === "edit") {
		btn_popup_save.show();
		btn_popup_edit.hide();
		btn_popup_delete.hide();
		grp_fileUpload.show();
		scwin.setFieldsReadOnly(false);
	}
};

scwin.setFieldsReadOnly = function(readOnly) {
	try {
		var editableFields = ["inp_defectName", "sel_priority", "sel_status", "cal_dueDate", "cal_fixedDate", "txt_description", "txt_responsePlan"];
		editableFields.forEach(function(fieldId) {
			var field = $p.getComponentById(fieldId);
			if (field && field.setReadOnly) {
				field.setReadOnly(readOnly);
			}
		});
	} catch(e) {
		console.error("필드 읽기 전용 설정 오류:", e);
	}
};

// 저장 버튼 클릭
scwin.btn_popup_save_onclick = function(e) {
	var defectName = dmp_defVoDetail.get("name");
	if (!defectName || defectName.trim() === "") {
		$c.win.alert("결함명을 입력해주세요.");
		return;
	}
	scwin.sendDefectAndFiles();
};

scwin.sendDefectAndFiles = function() {
	var formData = new FormData();
	formData.append("testId", dmp_defVoDetail.get("testId"));
	formData.append("name", dmp_defVoDetail.get("name"));
	formData.append("assignee", dmp_defVoDetail.get("assignee"));
	formData.append("fixDueDate", dmp_defVoDetail.get("fixDueDate"));
	formData.append("status", dmp_defVoDetail.get("status") || "NEW");
	formData.append("priority", dmp_defVoDetail.get("priority") || "MD");
	formData.append("description", dmp_defVoDetail.get("description"));
	formData.append("responsePlan", dmp_defVoDetail.get("responsePlan"));
	formData.append("fixedDate", dmp_defVoDetail.get("fixedDate"));

	if (mpd_html5Type && mpd_html5Type.fileArray) {
		var fileList = mpd_html5Type.fileArray;
		if (fileList && fileList.length > 0) {
			for (var i = 0; i < fileList.length; i++) {
				var realFile = fileList[i].file;
				formData.append("files", realFile);
			}
		}
	}

	fetch("/InsWebApp/DEF001InsWithFiles.pwkjson", {
		method: "POST",
		body: formData
	})
	.then(function(res) { return res.json(); })
	.then(function(res) {
		$c.win.alert("등록되었습니다.");
		dlt_Upload.removeAll();
		if (mpd_html5Type && mpd_html5Type.removeAllFiles) {
			mpd_html5Type.removeAllFiles();
		}
		pop_overlay.hide();
		scwin.btn_search_onclick();
	})
	.catch(function(err) {
		console.error("전송 실패", err);
		$c.win.alert("등록 중 오류가 발생했습니다.");
	});
};

// 수정 버튼 클릭
scwin.btn_popup_edit_onclick = function(e) {
	scwin.setFormMode("edit");
};

// 삭제 버튼 클릭
scwin.btn_popup_delete_onclick = function(e) {
	var defectId = dmp_defVoDetail.get("id");
	if (!defectId) {
		$c.win.alert("삭제할 결함을 선택해주세요.");
		return;
	}
	var promise = $c.win.confirm("결함을 삭제하시겠습니까?");
	promise.then(function(result) {
		if (result) {
			$c.sbm.execute($p, sbm_deleteDefVo);
		}
	});
};

// 서버 응답 처리
scwin.sbm_deleteDefVo_submitdone = function(e) {
	var elHeader = e.responseJSON.elHeader;
	if (!elHeader || elHeader.resSuc == false) {
		$c.win.alert(`에러코드 : ${elHeader.resCode}\n에러메시지 : ${elHeader.resMsg}`);
		return false;
	}
	$c.win.alert("삭제되었습니다.");
	pop_overlay.hide();
	scwin.btn_search_onclick();
};

scwin.sbm_updateDefVo_submitdone = function(e) {
	var elHeader = e.responseJSON.elHeader;
	if (!elHeader || elHeader.resSuc == false) {
		$c.win.alert(`에러코드 : ${elHeader.resCode}\n에러메시지 : ${elHeader.resMsg}`);
		return false;
	}
	$c.win.alert("수정되었습니다.");
	pop_overlay.hide();
	scwin.btn_search_onclick();
};

scwin.sbm_insertDefVo_submitdone = function(e) {
	var elHeader = e.responseJSON.elHeader;
	if (!elHeader || elHeader.resSuc == false) {
		$c.win.alert(`에러코드 : ${elHeader.resCode}\n에러메시지 : ${elHeader.resMsg}`);
		return false;
	}
	$c.win.alert("등록되었습니다.");
	pop_overlay.hide();
	scwin.btn_search_onclick();
};

// 파일 관련 함수
scwin.loadFileList = function() {
	var defectId = dmp_defVoDetail.get("id");
	if (defectId) {
		$c.sbm.execute($p, sbm_getDefFileList);
	}
};

scwin.sbm_getDefFileList_submitdone = function(e) {
	var elHeader = e.responseJSON.elHeader;
	if (!elHeader || elHeader.resSuc == false) {
		console.error("파일 목록 조회 실패:", elHeader ? elHeader.resMsg : "알 수 없는 오류");
		return false;
	}
};

scwin.multiUploadSelectDone = function() {
	var fileInfos = mpd_html5Type.getFileInfos();
	var newFileData = [];
	for (var i = 0; i < fileInfos.length; i++) {
		var file = fileInfos[i];
		newFileData.push({
			name: file.name,
			size: file.size,
			status: "업로드 대기"
		});
	}
	dlt_Upload.setJSON(newFileData);
};

scwin.btn_InitMultiupload_onclick = function(e) {
	dlt_Upload.removeAll();
	if (mpd_html5Type && mpd_html5Type.clear) {
		mpd_html5Type.clear();
	}
};

scwin.fileActionClick = function(row, col, colId, targetId) {
	var rowData = dlt_attVoList.getRowJSON(row);
	var fileId = rowData.fileId;
	var fileName = rowData.originalFileName;

	if (targetId.indexOf("download") >= 0 || col === 3) {
		scwin.downloadFile(fileId, fileName);
	} else if (targetId.indexOf("delete") >= 0) {
		scwin.deleteFile(fileId);
	}
};

scwin.downloadFile = function(fileId, fileName) {
	if (!fileId || !fileName) {
		alert("다운로드할 파일 정보가 없습니다.");
		return;
	}

	var downloadUrl = "/InsWebApp/FileDownload.pwkjson?fileId=" + encodeURIComponent(fileId);
	var iframe = document.createElement('iframe');
	iframe.style.display = 'none';
	iframe.src = downloadUrl;
	document.body.appendChild(iframe);

	setTimeout(function() {
		if (iframe.parentNode) {
			document.body.removeChild(iframe);
		}
	}, 2000);
};

scwin.deleteFile = function(fileId) {
	if (!fileId) {
		alert("삭제할 파일을 선택해주세요.");
		return;
	}

	var promise = $c.win.confirm("파일을 삭제하시겠습니까?");
	promise.then(function(result) {
		if (result) {
			fetch("/InsWebApp/DEF001FileDelete.pwkjson", {
				method: "POST",
				headers: { "Content-Type": "application/json" },
				body: JSON.stringify({ fileId: fileId })
			})
			.then(function(res) { return res.json(); })
			.then(function(res) {
				if (res.elHeader && res.elHeader.resSuc === true) {
					alert("파일이 삭제되었습니다.");
					scwin.loadFileList();
				} else {
					alert("파일 삭제 실패: " + (res.elHeader ? res.elHeader.resMsg : "알 수 없는 오류"));
				}
			})
			.catch(function(err) {
				console.error("파일 삭제 실패:", err);
				alert("파일 삭제 중 오류가 발생했습니다.");
			});
		}
	});
};

// 우선순위 렌더링
scwin.renderPriority = function(priority) {
	var priorityClass = "";
	var priorityText = "";

	switch(priority) {
		case "CR":
			priorityClass = "priority-critical";
			priorityText = "긴급";
			break;
		case "HI":
			priorityClass = "priority-high";
			priorityText = "높음";
			break;
		case "MD":
			priorityClass = "priority-medium";
			priorityText = "보통";
			break;
		case "LO":
			priorityClass = "priority-low";
			priorityText = "낮음";
			break;
		default:
			priorityClass = "priority-medium";
			priorityText = "보통";
	}

	return '<span class="priority-badge ' + priorityClass + '">' + priorityText + '</span>';
};

// 그리드 렌더링 함수
scwin.new_grd_onrenderrow = function(rowIndex) {
	var priorityValue = dlt_waitingList.getCellData(rowIndex, "priority");
	var cell = new_grd.getCell(rowIndex, "priority");
	if (cell) {
		cell.innerHTML = scwin.renderPriority(priorityValue);
	}
};

scwin.processing_grd_onrenderrow = function(rowIndex) {
	var priorityValue = dlt_processingList.getCellData(rowIndex, "priority");
	var cell = processing_grd.getCell(rowIndex, "priority");
	if (cell) {
		cell.innerHTML = scwin.renderPriority(priorityValue);
	}
};

scwin.completed_grd_onrenderrow = function(rowIndex) {
	var priorityValue = dlt_completedList.getCellData(rowIndex, "priority");
	var cell = completed_grd.getCell(rowIndex, "priority");
	if (cell) {
		cell.innerHTML = scwin.renderPriority(priorityValue);
	}
};
